using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedDodgeEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedDodge Effect")]
public class CorruptedDodgeEffect : Effect
{
	[Header("Counter Effects")]
	[SerializeField]
	private CorruptedRiposteEffect corruptedRiposteEffect;

	[SerializeField]
	private CorruptedCriticalEffect corruptedCriticalEffect;

	[SerializeField]
	private int corruptedCriticalEffectAmount;

	[SerializeField]
	private int decreaseCorruptedDodgeAmount;

	[NonSerialized]
	private int startingAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), amount, base.localizationManager.GetLocalizedThenDecreaseEffect(this, decreaseCorruptedDodgeAmount).RemoveLast(), corruptedCriticalEffect.GetEffectName(), corruptedCriticalEffectAmount, base.localizationManager.GetLocalizedAtTheEndOfEnemiesTurn(), startingAmount) + AppendedDescription();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		hideEffectValue = false;
		startingAmount = effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		hideEffectValue = false;
		if (startingAmount - effectAmount > 0)
		{
			effectOwner.GetComponent<UnitEffects>().AddEffect(this, startingAmount - effectAmount, effectFeedback: false, callEffectsCallbacks: false);
		}
		Debug.Log("DODGE PURIFY************" + effectOwner.GetComponent<UnitEffects>().IsEffectActiveGetAmount(this, activateFeedback: false));
		return effectAmount;
	}

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), corruptedCriticalEffectAmount);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, corruptedCriticalEffectAmount);
	}

	public bool CheckDodgePurify(int chanceAmount, UnitEffects unitEffects, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (source == null || ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source) || corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.PIERCE)
		{
			return false;
		}
		if (RandomUtilities.RandomChance(chanceAmount))
		{
			DodgeTriggered(unitEffects, source);
			if (chanceAmount == 25)
			{
				hideEffectValue = true;
			}
			unitEffects.IsEffectActiveAndDecreaseEffect(this, 25, activateFeedback: true, removeOnZero: false);
			SpawnVFX(GetVFXOwnerPosition(unitEffects.gameObject), 2f);
			if (IsVFXEnabled())
			{
				PlayEffectActivationSFX();
			}
			return true;
		}
		return false;
	}

	public void DodgeTriggered(UnitEffects unitEffects, GameObject source)
	{
		if (unitEffects.GetComponent<CorruptionStats>().CurrentCorruption > 0f)
		{
			unitEffects.AddEffect(corruptedCriticalEffect, corruptedCriticalEffectAmount);
			unitEffects.IsEffectActiveWithActivationWithSource(corruptedRiposteEffect, source, activateFeedback: false);
		}
	}
}
